def transform_demo1(grid):
    """Demo 1: shift non-bg non-0 cells by +2 rows, -6 cols"""
    bg = max(set(sum(grid, [])), key=sum(grid, []).count)
    result = [row[:] for row in grid]  # copy

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != bg and grid[r][c] != 0:
                new_r, new_c = r + 2, c - 6
                if 0 <= new_r < len(result) and 0 <= new_c < len(result[0]):
                    result[new_r][new_c] = grid[r][c]

    return result

